40	struct acl_gemm_sve_data {
41	    std::vector<float> A;
42	    std::vector<float> B;
43	    std::vector<float> golden;
44	};
45	
46	static void naive_gemm(const float *A, const float *B, float *C)
47	{
48	    for (int i = 0; i < GEMM_DIM; ++i)
49	        for (int j = 0; j < GEMM_DIM; ++j) {
50	            float acc = 0.0f;
51	            for (int k = 0; k < GEMM_DIM; ++k) {
52	                /* fmaf: 单次舍入 fused 乘加, 与 SVE svmla(FMLA)舍入序
53	                 * 一致 -> 有限值输入下位级可比较。 */
54	                acc = std::fmaf(A[i * GEMM_DIM + k], B[k * GEMM_DIM + j], acc);
55	            }
56	            C[i * GEMM_DIM + j] = acc;
57	        }
58	}
59	
60	static int acl_gemm_sve_init(struct test *test)
61	{
62	#if defined(__aarch64__)
63	    unsigned long hwcap = getauxval(AT_HWCAP);
64	    if ((hwcap & HWCAP_SVE) == 0) {
