67	        return EXIT_SKIP;
68	    }
69	#endif
70	    auto *d = new acl_gemm_sve_data;
71	    d->A.resize(GEMM_DIM * GEMM_DIM);
72	    d->B.resize(GEMM_DIM * GEMM_DIM);
73	    d->golden.resize(GEMM_DIM * GEMM_DIM);
74	    memset_random(d->A.data(), d->A.size() * sizeof(float));
75	    memset_random(d->B.data(), d->B.size() * sizeof(float));
76	    /* memset_random 任意位模式, 每矩阵约 1/256 元素为 NaN/Inf。NaN
77	     * payload 传播是 IEEE-754 实现自由(同类定性见 fpu_special_values_sve),
78	     * GEMM golden 无法对 NaN 位级比较; 过滤为有限值。特殊值边界行为
79	     * 由 fpu_special_values_sve 专门覆盖。 */
80	    for (size_t idx = 0; idx < d->A.size(); ++idx)
81	        if (!std::isfinite(d->A[idx]))
82	            d->A[idx] = 1.5f;
83	    for (size_t idx = 0; idx < d->B.size(); ++idx)
84	        if (!std::isfinite(d->B[idx]))
85	            d->B[idx] = 1.5f;
86	    naive_gemm(d->A.data(), d->B.data(), d->golden.data());
87	    test->data = d;
88	    return EXIT_SUCCESS;
89	}
