93	{
94	    (void)cpu;
95	    auto *d = static_cast<acl_gemm_sve_data *>(test->data);
96	    std::vector<float> C(GEMM_DIM * GEMM_DIM);
97	    const int lanes = svcntw();
98	    float brow[64];
99	
100	    TEST_LOOP(test, 64) {
101	        /* SVE GEMM: 每 i 行的累加器向量按 j-lane 展开, K 步进 svmla */
102	        for (int i = 0; i < GEMM_DIM; ++i) {
103	            for (size_t jbase = 0; jbase < (size_t)GEMM_DIM; jbase += lanes) {
104	                int n = (GEMM_DIM - (int)jbase < lanes) ? GEMM_DIM - (int)jbase : lanes;
105	                svbool_t pg = svwhilelt_b32((uint64_t)0, (uint64_t)n);
106	                svfloat32_t acc = svdup_f32(0.0f);
