4	 * SPDX-License-Identifier: Apache-2.0
5	 *
6	 * @test @b gmp_bigadd_sve
7	 * @parblock
8	 * SVE port of gmp_bigadd: large-integer addition via the SVE carry chain
9	 * (svadd lanes + serial carry fold, verified equivalent to __int128 on 20k
10	 * random chains) replacing the GMP mpz_add run path; golden stays the
11	 * __int128 software reference. Random operands per init via framework RNG.
12	 * @endparblock
13	 */
14	
15	#include "sandstone.h"
16	#include <cstdint>
17	#include <cstdio>
18	#include <cstring>
19	#include <vector>
20	
21	#if defined(__aarch64__)
22	#include <arm_sve.h>
23	#include <sys/auxv.h>
24	
25	#ifndef HWCAP_SVE
26	#define HWCAP_SVE (1 << 22)
27	#endif
28	#endif
29	
30	static constexpr size_t GMP_SVE_LIMBS = 256;   /* 2048-bit operands */
31	
32	struct GmpBigaddSveData {
33	    std::vector<uint64_t> a;
34	    std::vector<uint64_t> b;
35	    std::vector<uint64_t> golden;
36	};
37	
38	static void compute_golden(const GmpBigaddSveData *d, uint64_t *out, size_t n)
39	{
40	    uint64_t carry = 0;
41	    for (size_t i = 0; i < n; ++i) {
42	        unsigned __int128 s = (unsigned __int128)d->a[i] + d->b[i] + carry;
43	        out[i] = (uint64_t)s;
44	        carry = (uint64_t)(s >> 64);
45	    }
46	}
47	
48	static int gmp_bigadd_sve_init(struct test *test)
49	{
50	#if defined(__aarch64__)
51	    unsigned long hwcap = getauxval(AT_HWCAP);
52	    if ((hwcap & HWCAP_SVE) == 0) {
53	        log_skip(CpuNotSupportedSkipCategory,
54	                 "to be implemented (placeholder): ARM SVE required for gmp_bigadd_sve");
55	        return EXIT_SKIP;
56	    }
57	#endif
58	    auto *d = new GmpBigaddSveData;
59	    d->a.resize(GMP_SVE_LIMBS);
60	    d->b.resize(GMP_SVE_LIMBS);
61	    d->golden.resize(GMP_SVE_LIMBS);
62	    memset_random(d->a.data(), GMP_SVE_LIMBS * sizeof(uint64_t));
63	    memset_random(d->b.data(), GMP_SVE_LIMBS * sizeof(uint64_t));
64	    compute_golden(d, d->golden.data(), GMP_SVE_LIMBS);
65	    test->data = d;
66	    return EXIT_SUCCESS;
67	}
68	
69	#if defined(__aarch64__)
70	static int gmp_bigadd_sve_run(struct test *test, int cpu)
71	{
72	    (void)cpu;
73	    auto *d = static_cast<GmpBigaddSveData *>(test->data);
74	    std::vector<uint64_t> result(GMP_SVE_LIMBS);
75	    const int lanes = svcntd();
76	
77	    TEST_LOOP(test, 1 << 13) {
78	        /* SVE 进位链 (GMP mpz_add 的 SVE 替代): svadd 批 + 串行进位折叠 */
79	        uint64_t carry = 0;
80	        for (size_t base = 0; base < GMP_SVE_LIMBS; base += lanes) {
81	            int n = (GMP_SVE_LIMBS - base < (size_t)lanes) ? (int)(GMP_SVE_LIMBS - base) : lanes;
82	            svbool_t pg = svwhilelt_b64((uint64_t)0, (uint64_t)n);
83	            svuint64_t va = svld1_u64(pg, d->a.data() + base);
84	            svuint64_t vb = svld1_u64(pg, d->b.data() + base);
85	            uint64_t vsum[8];
86	            svst1_u64(pg, vsum, svadd_u64_x(pg, va, vb));
87	            for (int i = 0; i < n; ++i) {
88	                unsigned __int128 s = (unsigned __int128)vsum[i] + carry;
89	                result[base + i] = (uint64_t)s;
90	                uint64_t cin_ab = (vsum[i] < d->a[base + i]) ? 1u : 0u;
91	                carry = cin_ab + (uint64_t)(s >> 64);
92	            }
93	        }
94	        if (memcmp(result.data(), d->golden.data(), GMP_SVE_LIMBS * sizeof(uint64_t)) != 0) {
95	            report_fail_msg("gmp_bigadd_sve: big-integer add miscompare (SVE carry chain)");
96	        }
97	    }
98	    return EXIT_SUCCESS;
99	}
100	#else
101	static int gmp_bigadd_sve_run(struct test *test, int cpu)
102	{
103	    (void)test; (void)cpu;
104	    return EXIT_SKIP;
105	}
106	#endif
107	
108	static int gmp_bigadd_sve_finish(struct test *test)
109	{
110	    delete static_cast<GmpBigaddSveData *>(test->data);
111	    return EXIT_SUCCESS;
112	}
113	
114	DECLARE_TEST(gmp_bigadd_sve, "Large-integer addition on the SVE carry chain (2048-bit, port of gmp_bigadd)")
115	    .groups = DECLARE_TEST_GROUPS(&group_math),
116	    .test_init = gmp_bigadd_sve_init,
117	    .test_run = gmp_bigadd_sve_run,
118	    .test_cleanup = gmp_bigadd_sve_finish,
119	    .quality_level = TEST_QUALITY_PROD,
120	END_DECLARE_TEST
