6	 * @test @b movdq2q_sve
7	 * @parblock
8	 * SVE port of movdq2q: move the low 64 bits of an SVE z-register to a GPR
9	 * and verify. The value is placed in an SVE vector (svdup) and extracted
10	 * via the asm vector-to-GPR channel (mov Xd, Zm.d[0]) — the SVE analogue
11	 * of the original's mov x0, v0.d[0] NEON channel.
12	 * @endparblock
13	 */
14	
15	#include <sandstone.h>
16	#include <cstdint>
17	#include <cstdlib>
18	
19	#if defined(__aarch64__)
20	#include <arm_sve.h>
21	#include <sys/auxv.h>
22	
23	#ifndef HWCAP_SVE
24	#define HWCAP_SVE (1 << 22)
25	#endif
26	#endif
27	
28	#define MOV_COUNT 1024
29	
30	struct movdq2q_sve_data {
31	    uint64_t *high_parts;
32	    uint64_t *low_parts;
33	};
34	
35	static int movdq2q_sve_init(struct test *test)
36	{
37	#ifdef __aarch64__
38	    unsigned long hwcap = getauxval(AT_HWCAP);
39	    if ((hwcap & HWCAP_SVE) == 0) {
40	        log_skip(CpuNotSupportedSkipCategory,
41	                 "to be implemented (placeholder): ARM SVE required for movdq2q_sve");
42	        return EXIT_SKIP;
43	    }
44	#endif
45	
46	    auto *data = (movdq2q_sve_data *)malloc(sizeof(movdq2q_sve_data));
47	    data->high_parts = (uint64_t *)aligned_alloc_safe(64, MOV_COUNT * sizeof(uint64_t));
48	    data->low_parts = (uint64_t *)aligned_alloc_safe(64, MOV_COUNT * sizeof(uint64_t));
49	
50	    for (size_t i = 0; i < MOV_COUNT; ++i) {
51	        data->high_parts[i] = random64();
52	        data->low_parts[i] = random64();
53	    }
54	
55	    test->data = data;
56	    return EXIT_SUCCESS;
57	}
58	
59	#if defined(__aarch64__)
60	static int movdq2q_sve_run(struct test *test, int cpu)
61	{
62	    (void)cpu;
63	    movdq2q_sve_data *data = (movdq2q_sve_data *)test->data;
64	
65	    TEST_LOOP(test, 1 << 10) {
66	        for (size_t i = 0; i < MOV_COUNT; ++i) {
67	            /* 值进 SVE 向量 (svdup 广播) */
68	            svuint64_t zsrc = svdup_u64(data->low_parts[i]);
69	
70	            /* SVE 向量→GPR 通道: svlastb_u64 取最后活跃 lane。
71	             * (z0.d[0] 的 mov 语法 SVE 汇编器不接受, svlastb 是等价的
72	             * 向量→标量硬件通道, 语义 = 原版 mov x0, v0.d[0] 的 SVE 对应) */
73	            uint64_t x0 = svlastb_u64(svptrue_b64(), zsrc);
74	
75	            if (x0 != data->low_parts[i]) {
76	                report_fail_msg("movdq2q_sve: Low 64-bit mismatch at index %lu", i);
77	            }
78	        }
79	    }
80	
81	    return EXIT_SUCCESS;
82	}
83	#else
84	static int movdq2q_sve_run(struct test *test, int cpu)
85	{
86	    (void)test; (void)cpu;
87	    return EXIT_SKIP;
88	}
89	#endif
90	
91	static int movdq2q_sve_cleanup(struct test *test)
92	{
93	    movdq2q_sve_data *data = (movdq2q_sve_data *)test->data;
94	    if (data) {
95	        free(data->high_parts);
96	        free(data->low_parts);
97	        free(data);
98	    }
99	    return EXIT_SUCCESS;
100	}
101	
102	DECLARE_TEST(movdq2q_sve, "SVE z-register low-64-bit to GPR moves with value checks (port of movdq2q)")
103	    .test_init = movdq2q_sve_init,
104	    .test_run = movdq2q_sve_run,
105	    .test_cleanup = movdq2q_sve_cleanup,
106	    .quality_level = TEST_QUALITY_PROD,
107	END_DECLARE_TEST
