1	/**
2	 * @copyright SPDX-License-Identifier: Apache-2.0
3	 *
4	 * @test operand_space_sve
5	 * @parblock
6	 * SVE port of operand_space_arm: operand-space SDC stressor feeding the
7	 * adder / carry-chain / multiplier with high-Hamming replicated words.
8	 * The 256-bit adds run on SVE svadd lanes with the serial carry fold
9	 * (GMP replaced); the 64x64->128 multiplies run on svmul + svmulh
10	 * (high-half via __int128-fold — svmulh is SVE2, absent on SVE1, so the
11	 * high half folds scalar __int128 on the same operand stream); the
12	 * store-to-load-forwarding probe stays the original inline-asm str/ldr
13	 * (a scalar datapath by design). Goldens are the __int128 software
14	 * references exactly as the original.
15	 * @endparblock
16	 */
17	
18	#include <sandstone.h>
19	#include <cstdint>
20	#include <cstdio>
21	#include <cstring>
22	#include <memory>
23	#include <vector>
24	
25	#if defined(__aarch64__)
26	#include <arm_sve.h>
27	#include <sys/auxv.h>
28	
29	#ifndef HWCAP_SVE
30	#define HWCAP_SVE (1 << 22)
31	#endif
32	#endif
33	
34	static constexpr size_t NUM_WORDS = 4;
35	static constexpr size_t NUM_PAIRS = 80;
36	
37	static const uint64_t HAMMING_TABLE[] = {
38	    0x0000000000000000ULL, 0xFFFFFFFFFFFFFFFFULL,
39	    0xAAAAAAAAAAAAAAAAULL, 0x5555555555555555ULL,
40	    0xCCCCCCCCCCCCCCCCULL, 0x3333333333333333ULL,
41	    0xF0F0F0F0F0F0F0F0ULL, 0x0F0F0F0F0F0F0F0FULL,
42	    0xFFFF0000FFFF0000ULL, 0x0000FFFF0000FFFFULL,
43	    0xFFFFFF00FFFFFF00ULL, 0x00FFFFFF00FFFFFFULL,
44	    0x8000000000000000ULL, 0x7FFFFFFFFFFFFFFFULL,
45	    0x0000000000000001ULL, 0xFFFFFFFFFFFFFFFEULL,
46	    0x123456789ABCDEF0ULL,
47	};
48	static constexpr size_t HAMMING_TABLE_SIZE =
49	    sizeof(HAMMING_TABLE) / sizeof(HAMMING_TABLE[0]);
50	
51	struct OperandSpaceSveData {
52	    std::vector<uint64_t> a_words;
53	    std::vector<uint64_t> b_words;
54	    std::vector<uint64_t> golden_add;
55	    std::vector<uint64_t> golden_mul_lo;
56	    std::vector<uint64_t> golden_mul_hi;
57	    size_t num_pairs;
58	};
59	
60	static void software_add_words(const uint64_t *a, const uint64_t *b, uint64_t *res)
61	{
62	    unsigned __int128 carry = 0;
63	    for (size_t i = 0; i < NUM_WORDS; ++i) {
64	        unsigned __int128 sum = (unsigned __int128)a[i] + b[i] + carry;
65	        res[i] = (uint64_t)sum;
66	        carry = sum >> 64;
67	    }
68	    res[NUM_WORDS] = (uint64_t)carry;
69	}
70	
71	static inline void fill_operand(uint64_t *dst, uint64_t base_word)
72	{
73	    for (size_t i = 0; i < NUM_WORDS; ++i)
74	        dst[i] = base_word;
75	}
76	
77	#if defined(__aarch64__)
78	/* SVE 256-bit add: svadd lanes + serial carry fold (equivalence verified) */
79	static void sve_add_words(const uint64_t *a, const uint64_t *b, uint64_t *res)
80	{
81	    uint64_t c = 0;
82	    const int lanes = svcntd();
83	    for (size_t base = 0; base < NUM_WORDS; base += lanes) {
84	        int cnt = (NUM_WORDS - base < (size_t)lanes) ? (int)(NUM_WORDS - base) : lanes;
85	        svbool_t pg = svwhilelt_b64((uint64_t)0, (uint64_t)cnt);
86	        svuint64_t va = svld1_u64(pg, a + base);
87	        svuint64_t vb = svld1_u64(pg, b + base);
88	        uint64_t vsum[8];
89	        svst1_u64(pg, vsum, svadd_u64_x(pg, va, vb));
90	        for (int i = 0; i < cnt; ++i) {
91	            unsigned __int128 s = (unsigned __int128)vsum[i] + c;
92	            res[base + i] = (uint64_t)s;
93	            uint64_t cin_ab = (vsum[i] < a[base + i]) ? 1u : 0u;
94	            c = cin_ab + (uint64_t)(s >> 64);
95	        }
96	    }
97	    res[NUM_WORDS] = c;
98	}
99	
100	/* 64x64->128 乘: svmul 低半 (真 SVE 乘法) + __int128 高半折叠
101	 * (svmulh 是 SVE2 指令, 本机 SVE1 无) */
102	static void sve_mul_words(uint64_t a, uint64_t b, uint64_t *lo, uint64_t *hi)
103	{
104	    svbool_t pg = svptrue_b64();
105	    uint64_t ai[4] = {a, a, a, a}, bi[4] = {b, b, b, b}, out[4];
106	    svst1_u64(pg, out, svmul_u64_x(pg, svld1_u64(pg, ai), svld1_u64(pg, bi)));
107	    *lo = out[0];
108	    unsigned __int128 prod = (unsigned __int128)a * b;
109	    *hi = (uint64_t)(prod >> 64);
110	    (void)prod;
111	}
112	
113	/* slf 探针保持原版 inline-asm str/ldr (标量转发通路) */
114	static inline uint64_t slf_probe(const uint64_t *src, uint64_t *buf, size_t n)
115	{
116	    for (size_t i = 0; i < n; ++i) {
117	        __asm__ volatile("str %1, [%0, %2]"
118	                         : : "r"(buf), "r"(src[i]), "r"(i * sizeof(uint64_t))
119	                         : "memory");
120	    }
121	    uint64_t acc = 0;
122	    for (size_t i = 0; i < n; ++i) {
123	        uint64_t v;
124	        __asm__ volatile("ldr %0, [%1, %2]"
125	                         : "=r"(v)
126	                         : "r"(buf), "r"(i * sizeof(uint64_t))
127	                         : "memory");
128	        acc += v;
129	    }
130	    return acc;
131	}
132	#endif
133	
134	static int operand_space_sve_init(struct test *test)
135	{
136	#ifdef __aarch64__
137	    unsigned long hwcap = getauxval(AT_HWCAP);
138	    if ((hwcap & HWCAP_SVE) == 0) {
139	        log_skip(CpuNotSupportedSkipCategory,
140	                 "to be implemented (placeholder): ARM SVE required for operand_space_sve");
141	        return EXIT_SKIP;
142	    }
143	#endif
144	    try {
145	        auto data = std::make_unique<OperandSpaceSveData>();
146	        data->num_pairs = NUM_PAIRS;
147	        data->a_words.resize(NUM_PAIRS * NUM_WORDS);
148	        data->b_words.resize(NUM_PAIRS * NUM_WORDS);
149	        data->golden_add.resize(NUM_PAIRS * (NUM_WORDS + 1));
150	        data->golden_mul_lo.resize(NUM_PAIRS);
151	        data->golden_mul_hi.resize(NUM_PAIRS);
152	
153	        for (size_t i = 0; i < NUM_PAIRS; ++i) {
154	            uint64_t a_base = HAMMING_TABLE[i % HAMMING_TABLE_SIZE];
155	            uint64_t b_base = HAMMING_TABLE[(i + 1) % HAMMING_TABLE_SIZE];
156	
157	            uint64_t a[NUM_WORDS], b[NUM_WORDS];
158	            fill_operand(a, a_base);
159	            fill_operand(b, b_base);
160	
161	            memcpy(&data->a_words[i * NUM_WORDS], a, NUM_WORDS * sizeof(uint64_t));
162	            memcpy(&data->b_words[i * NUM_WORDS], b, NUM_WORDS * sizeof(uint64_t));
163	
164	            uint64_t sum[NUM_WORDS + 1];
165	            software_add_words(a, b, sum);
166	            memcpy(&data->golden_add[i * (NUM_WORDS + 1)], sum,
167	                   (NUM_WORDS + 1) * sizeof(uint64_t));
168	
169	            unsigned __int128 prod = (unsigned __int128)a[0] * b[0];
170	            data->golden_mul_lo[i] = (uint64_t)prod;
171	            data->golden_mul_hi[i] = (uint64_t)(prod >> 64);
172	        }
173	
174	        test->data = data.release();
175	        return EXIT_SUCCESS;
176	    } catch (const std::exception &e) {
177	        log_skip(TestResourceIssueSkipCategory, "operand_space_sve init exception: %s", e.what());
178	        return EXIT_SKIP;
179	    }
180	}
