16	static constexpr size_t VECTOR_SIZE = 8;   // 8 个单精度浮点数（与原版一致）
17	
18	// 软件参考：使用 fmaf 逐元素计算（单次舍入）
19	static void software_fma(const float *a, const float *b, const float *c, float *ref) {
20	    for (int i = 0; i < (int)VECTOR_SIZE; ++i) {
21	        ref[i] = fmaf(a[i], b[i], c[i]);
22	    }
23	}
24	
25	// 比较两个浮点数数组是否近似相等（允许 1e-6 相对误差，与原版一致）
26	static bool approx_equal(const float *x, const float *y) {
27	    for (int i = 0; i < (int)VECTOR_SIZE; ++i) {
28	        float diff = fabsf(x[i] - y[i]);
29	        float tol = 1e-6f * fmaxf(fabsf(x[i]), fabsf(y[i]));
30	        if (diff > tol && diff > 1e-7f) {
31	            return false;
32	        }
33	    }
34	    return true;
35	}
