39	static int fma_sve_init(struct test *test) {
40	    (void)test;
41	#ifdef __aarch64__
42	    unsigned long hwcap = getauxval(AT_HWCAP);
43	    if ((hwcap & HWCAP_SVE) == 0) {
44	        log_skip(CpuNotSupportedSkipCategory,
