52	#ifdef __aarch64__
53	static int fma_sve_run(struct test *test, int cpu) {
54	    (void)cpu;
55	    // 每个线程独立分配数据（栈上）
56	    float a[VECTOR_SIZE];
57	    float b[VECTOR_SIZE];
58	    float c[VECTOR_SIZE];
59	    float result[VECTOR_SIZE];
60	
61	    std::mt19937 rng(std::random_device{}());
62	    std::uniform_real_distribution<float> dist(-100.0f, 100.0f);
63	
64	    do {
65	        // 生成随机向量 a, b, c
66	        for (int i = 0; i < (int)VECTOR_SIZE; ++i) {
67	            a[i] = dist(rng);
68	            b[i] = dist(rng);
69	            c[i] = dist(rng);
70	        }
71	
72	        // ---- 硬件 FMA 计算 (SVE): svmla_f32_x 即 c + a*b, VL 无关分批 ----
73	        for (size_t base = 0; base < VECTOR_SIZE; base += svcntw()) {
74	            svbool_t pg = svwhilelt_b32((uint64_t)base, (uint64_t)VECTOR_SIZE);
75	            svfloat32_t va = svld1_f32(pg, a + base);
76	            svfloat32_t vb = svld1_f32(pg, b + base);
77	            svfloat32_t vc = svld1_f32(pg, c + base);
78	            svst1_f32(pg, result + base, svmla_f32_x(pg, vc, va, vb));
79	        }
80	
81	        // ---- 软件参考计算 ----
82	        float ref[VECTOR_SIZE];
83	        software_fma(a, b, c, ref);
84	
85	        // 比较硬件结果与参考
86	        bool data_ok = approx_equal(result, ref);
87	
88	        // 一致性测试：存储硬件结果到内存再加载比较
89	        float store_buf[VECTOR_SIZE];
90	        memcpy(store_buf, result, sizeof(store_buf));
91	        float reload_buf[VECTOR_SIZE];
92	        memcpy(reload_buf, store_buf, sizeof(store_buf));
93	        bool consistent = (memcmp(reload_buf, result, sizeof(reload_buf)) == 0);
94	
95	        if (!(data_ok && consistent)) {
96	            report_fail_msg("fma_sve: FMA result mismatch or consistency failure");
97	            return EXIT_FAILURE;
98	        }
99	
100	    } while (test_time_condition(test));
101	
102	    return EXIT_SUCCESS;
103	}
104	#else
105	static int fma_sve_run(struct test *test, int cpu) {
106	    (void)cpu;
107	    log_skip(TestResourceIssueSkipCategory,
108	             "to be implemented (placeholder): ARM SVE FMA required");
109	    return EXIT_SKIP;
110	}
111	#endif
112	
113	static int fma_sve_finish(struct test *test) {
114	    (void)test;
115	    return EXIT_SUCCESS;
116	}
