===== write_only_int 60-85（passed=false 上下文）=====
        bool passed = true;
        int32_t first_vals[VECTOR_SIZE]; // 用于输出本次的输入

        for (size_t i = 0; i < PER_THREAD_SIZE; i += VECTOR_SIZE) {
            // 生成 VECTOR_SIZE 个随机数
            int32_t vals[VECTOR_SIZE];
            for (int j = 0; j < VECTOR_SIZE; ++j) {
                vals[j] = dist(rng);
                if (i == 0) first_vals[j] = vals[j]; // 保存前几个用于输出
            }

            // 使用 SVE 存储
            svbool_t pg = svwhilelt_b32((uint64_t)0, (uint64_t)VECTOR_SIZE);
            svint32_t v = svld1_s32(pg, vals);
            svst1_s32(pg, buf + i, v);

            // 立即读回验证
            svint32_t loaded = svld1_s32(pg, buf + i);
            int32_t loaded_vals[VECTOR_SIZE];
            svst1_s32(pg, loaded_vals, loaded);
            for (int j = 0; j < VECTOR_SIZE; ++j) {
                if (loaded_vals[j] != vals[j]) {
                    passed = false;
                    break;
                }
            }
===== read_L3_int 70-92 =====
        // 顺序读取整个数组（SVE 谓词分批，每次 VECTOR_SIZE 个 int32）
        for (size_t i = 0; i < ARRAY_SIZE; i += VECTOR_SIZE) {
            svbool_t pg = svwhilelt_b32((uint64_t)0, (uint64_t)VECTOR_SIZE);
            svint32_t v = svld1_s32(pg, td->data + i);
            int32_t vals[VECTOR_SIZE];
            svst1_s32(pg, vals, v);
            for (int j = 0; j < VECTOR_SIZE; ++j) {
                local_sum += (uint64_t)vals[j];
            }
        }

        bool passed = (local_sum == td->golden_sum);

        // 输出本次的输入（数组前 4 个元素）和结果
        fprintf(stderr, "mesh_upi_sve_read_L3_int: Thread %d, data[0..3]=(%d,%d,%d,%d), local_sum=%lu, golden_sum=%lu, result=%s%s%s\n",
                id,
                td->data[0], td->data[1], td->data[2], td->data[3],
                local_sum, td->golden_sum,
                passed ? GREEN : RED,
                passed ? "PASS" : "FAIL",
                RESET);
        fflush(stderr);

